#include <stdio.h>
int main(void) {
    int state = 9, acc = 0, last = 0;
    switch (2) {
        case 1: state += 10; break;
        case 2: state = 4;
        case 3: state += 5;
        default: state--;
    }
    for (int i = 1; i <= 6; i++) {
        if (i % 2 != 0) continue;
        acc += i;
        last = i;
    }
    printf("%d\n%d %d\n", state, acc, last);
    return 0;
}

