#include <stdio.h>
struct Item { int x; int y; };
int main(void) {
    struct Item items[] = {{2, 5}, {7, 3}, {4, 8}};
    struct Item *p = items;
    p++;
    p->x += (p + 1)->y;
    int *refs[] = {&items[0].x, &items[1].x};
    printf("%d %d %d\n", p->x, p->y, (p - 1)->x);
    printf("%d %d\n", *refs[1], **refs);
    return 0;
}

class Parent {
    int x = 2;
    int score() { return x; }
    int score(int k) { return x + k; }
}
class Child extends Parent {
    int x = 9;
    Child() { super.x = 4; }
    @Override int score(int k) { return x + k; }
    int score(String s) { return s.length(); }
}
public class Main {
    public static void main(String[] args) {
        Parent ref = new Child();
        System.out.println(ref.x);
        System.out.println(ref.score());
        System.out.println(ref.score(3));
    }
}

public class Main {
    static class Box { int n; }
    static void change(Box m) {
        m.n += 4;
        m = new Box();
        m.n = 100;
    }
    public static void main(String[] args) {
        Box a = new Box();
        a.n = 2;
        Box b = a;
        change(b);
        System.out.println(a.n + " " + b.n);
        b = new Box();
        b.n = 9;
        System.out.println(a.n + " " + b.n);
    }
}

#include <stdio.h>
int f(int n) {
    if (n <= 1) return 1;
    return n * f(n - 1);
}
int g(int n) {
    if (n <= 1) return n;
    return g(n - 1) + g(n - 3);
}
int main(void) {
    printf("%d %d\n", f(4), g(4));
    return 0;
}

#include <stdio.h>
int main(void) {
    int field[3][3] = {{1,0,0}, {0,1,0}, {0,0,0}};
    int count[3][3] = {{0}};
    for (int y = 0; y < 3; y++) {
        for (int x = 0; x < 3; x++) {
            if (field[y][x] == 0) continue;
            for (int dy = -1; dy <= 1; dy++) {
                for (int dx = -1; dx <= 1; dx++) {
                    int j = y + dy, i = x + dx;
                    if (0 <= j && j < 3 && 0 <= i && i < 3)
                        count[j][i]++;
                }
            }
        }
    }
    for (int y = 0; y < 3; y++)
        for (int x = 0; x < 3; x++)
            printf("%d%s", count[y][x], x == 2 ? "\n" : " ");
    return 0;
}
